function guessCheck(secret, guess){
  secret=Number(secret); guess=Number(guess);
  if(!(secret>0) || !(guess>0)) return {result:'invalid'};
  if(guess===secret) return {result:'hit'};
  return {result: guess<secret ? 'low' : 'high'};
}
function guessHint(lo, hi){
  lo=Number(lo)||1; hi=Number(hi)||100;
  if(hi<lo) { var t=lo; lo=hi; hi=t; }
  return Math.floor((lo+hi)/2);
}

var EXPORTS={guessCheck:guessCheck,guessHint:guessHint};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.NumberGuessForgePure = EXPORTS; }
